import pandas as pd


def run(inputs: dict) -> dict:
    orders = inputs['orders'].copy()
    ref_customers = inputs['ref_customers']
    ref_skus = inputs['ref_skus']

    # Build lookup maps; if duplicate keys exist, keep the first occurrence.
    cust_map = (
        ref_customers.drop_duplicates(subset='customer_id', keep='first')
        .set_index('customer_id')['status']
    )
    sku_map = (
        ref_skus.drop_duplicates(subset='sku', keep='first')
        .set_index('sku')
    )

    reasons = []

    for _, row in orders.iterrows():
        cust_id = row['customer_id']
        sku = row['sku']
        ship_country = row['ship_country']

        reason = None

        # R1: customer unknown
        if pd.isna(cust_id) or cust_id not in cust_map.index:
            reason = 'CUST_UNKNOWN'
        else:
            status = cust_map.loc[cust_id]
            # In case of duplicate index after drop_duplicates this is a scalar;
            # keep defensive handling just in case.
            if isinstance(status, pd.Series):
                status = status.iloc[0]
            if status != 'ACTIVE':
                reason = 'CUST_INACTIVE'
            else:
                # R3: sku unknown
                if pd.isna(sku) or sku not in sku_map.index:
                    reason = 'SKU_UNKNOWN'
                else:
                    sku_row = sku_map.loc[sku]
                    if isinstance(sku_row, pd.DataFrame):
                        sku_row = sku_row.iloc[0]

                    discontinued = sku_row['discontinued']
                    if pd.notna(discontinued) and int(discontinued) == 1:
                        reason = 'SKU_DISC'
                    else:
                        allowed = sku_row['allowed_countries']
                        if pd.notna(allowed) and str(allowed).strip() != '':
                            members = [m.strip() for m in str(allowed).split(',')]
                            if pd.isna(ship_country) or str(ship_country) not in members:
                                reason = 'CTRY_BLOCKED'

        reasons.append(reason)

    orders['reason_code'] = reasons

    clean_mask = orders['reason_code'].isna()
    orders_clean = orders[clean_mask].drop(columns=['reason_code']).reset_index(drop=True)
    orders_rejects = orders[~clean_mask].reset_index(drop=True)

    return {
        'orders_clean': orders_clean,
        'orders_rejects': orders_rejects,
    }
